import{_ as n}from"./chunks/onnx-export.i-QhCQcz.js";import{_ as t,o as r,c as o,a0 as s}from"./chunks/framework.Ckbw5VQO.js";const h=JSON.parse('{"title":"ONNX","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/models/onnx.md","filePath":"fr/guide/models/onnx.md"}'),a={name:"fr/guide/models/onnx.md"};function i(l,e,c,u,d,p){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="onnx" tabindex="-1"><a href="https://onnx.ai/" target="_blank" rel="noreferrer">ONNX</a> <a class="header-anchor" href="#onnx" aria-label="Permalink to &quot;[ONNX](https://onnx.ai/)&quot;">​</a></h1><p>Dans geo-ml, une fois le modèle YOLOv8 fine-tuné sur nos piscines &amp; bâtiments, il faut le faire tourner <strong>dans le navigateur</strong>, sans serveur, sans Python, sans GPU. C&#39;est là qu&#39;intervient ONNX : on exporte les poids entraînés dans un format universel (<code>.onnx</code>), que le navigateur charge et exécute directement via <strong><a href="https://onnxruntime.ai/docs/tutorials/web/" target="_blank" rel="noreferrer">ONNX Runtime Web</a></strong>. Le calcul d&#39;inférence se fait entièrement côté client, sur la machine de l&#39;utilisateur.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>ONNX</strong> (<em>Open Neural Network Exchange</em>) est un <strong>format de fichier universel</strong> pour les modèles de machine learning. Il permet d&#39;entraîner un modèle dans une bibliothèque (ici <a href="https://docs.pytorch.org/docs/2.12/onnx.html" target="_blank" rel="noreferrer">PyTorch</a> / <a href="https://docs.ultralytics.com/integrations/onnx" target="_blank" rel="noreferrer">Ultralytics</a>) et de l&#39;exécuter <strong>ailleurs</strong>, y compris dans un navigateur web, sans serveur.</p></div><h2 id="principe-de-fonctionnement" tabindex="-1">Principe de fonctionnement <a class="header-anchor" href="#principe-de-fonctionnement" aria-label="Permalink to &quot;Principe de fonctionnement&quot;">​</a></h2><p>Un modèle entraîné est attaché à son framework : un <code>.pt</code> PyTorch a besoin de PyTorch pour tourner. Or PyTorch ne tourne pas dans un navigateur.</p><p>ONNX découple le <strong>modèle</strong> de la <strong>bibliothèque d&#39;entraînement</strong> en sérialisant le graphe de calcul et les poids dans un fichier portable</p><div class="tip custom-block"><p class="custom-block-title">Graphe de calcul &amp; poids</p><ul><li><strong>Graphe de calcul</strong> : la <em>recette</em> du modèle, la liste ordonnée des opérations (convolutions, normalisations, activations…) et comment elles se chaînent. C&#39;est l&#39;architecture du réseau.</li><li><strong>Poids</strong> : les <em>valeurs numériques</em> apprises pendant l&#39;entraînement, des millions de nombres qui, combinés avec le graphe, produisent les détections. Sans les poids, le graphe est une coquille vide.</li></ul></div><img src="'+n+'" style="display:block;margin:1.5rem auto;width:100%;height:auto;"><div class="info custom-block"><p class="custom-block-title">INFO</p><p>N&#39;importe quel <em>runtime</em> ONNX compatible sait charger ce fichier et l&#39;exécuter.</p></div><h2 id="onnx-runtime-web" tabindex="-1"><a href="https://onnxruntime.ai/docs/tutorials/web/" target="_blank" rel="noreferrer">ONNX Runtime Web</a> <a class="header-anchor" href="#onnx-runtime-web" aria-label="Permalink to &quot;[ONNX Runtime Web](https://onnxruntime.ai/docs/tutorials/web/)&quot;">​</a></h2><p>Le projet est déployé <strong>sans backend</strong> (GitHub Pages). L&#39;inférence doit donc tourner côté client. C&#39;est le rôle d&#39;<strong>ONNX Runtime Web</strong> :</p><div class="tip custom-block"><p class="custom-block-title">Inférence</p><p>L&#39;<strong>inférence</strong> est l&#39;étape où le modèle <em>utilise</em> ce qu&#39;il a appris : on lui donne une image, il renvoie des prédictions (boîtes, classes, scores). C&#39;est l&#39;opposé de l&#39;entraînement, ici on ne modifie plus les poids, on les applique.</p></div><ul><li>il charge le <code>.onnx</code> directement dans la page</li><li>il l&#39;exécute en <strong><a href="https://webassembly.org/" target="_blank" rel="noreferrer">WebAssembly (WASM)</a></strong>, du code quasi-natif dans le navigateur</li></ul><div class="tip custom-block"><p class="custom-block-title">WebAssembly (WASM)</p><p>Format binaire exécutable par tous les navigateurs modernes, conçu pour tourner à une vitesse proche du natif. Il permet de faire tourner du code C++/Rust (ici le moteur ONNX) dans un onglet, sans plugin ni installation.</p></div>',14)])])}const b=t(a,[["render",i]]);export{h as __pageData,b as default};
